(function(){'use strict';
const $=s=>document.querySelector(s),E=MiniChess,API=window.PANLUDIQ_API||'',names={K:'킹',R:'룩',B:'비숍',P:'폰',G:'승급 폰'},glyph={K:'♚',R:'♜',B:'♝',P:'♟',G:'♟'};let token='',roomCode='',view=null,selection=null,busy=false,joined=false,stopped=false,storage=true;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pos=i=>'ABC'[i%3]+(4-Math.floor(i/3));const rid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
function status(text,error=false){$('#network').textContent=text;$('#network').classList.toggle('error',error)}
function store(){try{sessionStorage.setItem('panludiq.online.v1',JSON.stringify({token,roomCode}))}catch{storage=false}}
async function api(path,method='GET',data,initial=false){let response;try{response=await fetch(API+'/api'+path,{method,headers:{...(token?{Authorization:'Bearer '+token}:{}),...(method==='POST'?{'Content-Type':'application/json'}:{})},body:method==='POST'?JSON.stringify(data||{}):undefined,signal:AbortSignal.timeout(initial?90000:12000)})}catch{throw new Error('서버 연결을 확인해주세요. 첫 접속은 서버 준비로 1분 이상 걸릴 수 있습니다.')}let result;try{result=await response.json()}catch{throw new Error('서버 응답을 읽지 못했습니다. 잠시 후 다시 시도해주세요.')}if(!response.ok){if(response.status===401){token='';store()}let e=new Error(result.error||'요청을 처리하지 못했습니다.');e.code=response.status;throw e}return result}
function setView(v){if(view&&view.code===v.code&&view.version>v.version)return;let changed=!view||view.version!==v.version||JSON.stringify(view.players)!==JSON.stringify(v.players);if(view?.code===v.code){if(v.phase==='finished'&&view.phase!=='finished')Sound.play(v.game.result.winner===null?'select':v.game.result.winner===v.you?'win':'lose');else if(v.phase==='active'&&(view.phase!=='active'||v.game.ply!==view.game?.ply))Sound.play(view.phase!=='active'?'select':'correct')}view=v;roomCode=v.code;joined=true;store();$('#lobby').hidden=true;$('#room').hidden=false;if(changed)render();status('서버 연결됨 · '+(v.phase==='waiting'?'친구와 준비를 기다리는 중':v.phase==='finished'?'경기 종료':'서버 판정으로 대전 중'))}
function myTurn(){return view?.phase==='active'&&view.game.turn===view.you&&view.players.every(p=>p.connected)&&!busy}
function moves(){if(!selection||!myTurn())return [];return E.actions({...view.game,seen:{}}).filter(a=>selection.drop?a.drop===selection.drop:a.from===selection.from)}
function piece(pc,facing){return `<span class="piece ${pc.p===0?'blue-piece':'purple-piece'} ${facing?'enemy-facing':''}"><span class="glyph">${glyph[pc.t]}</span><span class="piece-name">${names[pc.t]}</span></span>`}
function hand(p){return `<div class="pocket"><span class="pocket-title ${p===0?'blue-piece':'purple-piece'}"><b>${p===view.you?'내':'상대'} 보유 말</b></span>${view.game.hands[p].length?[...new Set(view.game.hands[p])].map(t=>`<button class="hand-piece ${selection?.drop===t&&p===view.you?'chosen':''}" data-drop="${t}" aria-label="${p===view.you?'내':'상대'} ${names[t]} 재투입" ${p!==view.you||!myTurn()?'disabled':''}>${glyph[t]} ×${view.game.hands[p].filter(x=>x===t).length}</button>`).join(''):'<span class="empty-hand">없음</span>'}</div>`}
function render(){const v=view,g=v.game,me=v.you,invite=location.origin+location.pathname+'?room='+v.code;let players=v.players.map((p,i)=>`<div class="player-box ${i===me?'mine':''}"><b>${esc(p.name)} ${i===me?'(나)':''}</b><small>${i===0?'블루 · 선공':'퍼플 · 후공'} · ${p.connected?'연결됨':'연결 끊김'}${p.reconnectSeconds!==null?' · 복귀 '+p.reconnectSeconds+'초':''}</small><small>${v.phase==='waiting'?(p.ready?'준비 완료':'준비 대기'):p.rematch?'재대결 신청':''}</small></div>`);if(v.players.length===1)players.push('<div class="player-box"><b>친구를 기다리고 있어요</b><small>초대 링크나 코드를 보내주세요.</small></div>');let board='';
if(g){let order=Array.from({length:12},(_,i)=>me===1?11-i:i),candidates=moves();board=`<div class="online-layout"><section class="online-board-panel"><div class="turn-note">${g.result?(g.result.winner===null?'무승부':g.result.winner===me?'내가 승리했어요!':'상대가 승리했어요'):g.turn===me?'내 차례입니다.':'상대 차례입니다.'}${g.pending!==null&&!g.result?'<br>킹 진입! 상대 한 차례를 버티면 승리합니다.':''}</div>${hand(1-me)}<div id="online-board" class="chess-board" aria-label="온라인 대전 게임판">${order.map(i=>{let pc=g.board[i],target=candidates.some(a=>a.to===i),danger=pc?.t==='K'&&E.threatened(g,i);return `<button class="square ${(Math.floor(i/3)+i%3)%2?'alt':''} ${target?(pc?'capture':'target'):''} ${selection?.from===i?'chosen':''}" data-cell="${i}" aria-label="${pos(i)} ${pc?(pc.p===me?'내 ':'상대 ')+names[pc.t]:'빈칸'}${target?' 이동 가능':''}" ${!myTurn()?'disabled':''}><span class="coord">${pos(i)}</span>${pc?piece(pc,pc.p!==me):target?'·':''}${danger?'<span class="mark">!</span>':''}${pc?.t==='G'?'<span class="promotion">승급</span>':''}</button>`}).join('')}</div>${hand(me)}<p class="mini-hint">${selection?'표시된 칸을 눌러 이동·재투입하세요.':'내 말 또는 보유 말을 누르면 가능한 칸이 표시됩니다.'}</p><p class="note">모든 말은 1칸 이동 · 킹 8방향 / 룩 상하좌우 / 비숍 대각선 / 폰 앞으로<br>킹 포획 또는 상대 끝줄 진입 후 상대 한 차례 생존 시 승리.<br>승급 폰은 뒤쪽 대각선을 제외한 6방향 이동. 잡은 말은 내 말로 재투입.</p></section><aside><section class="mini-card"><h2>경기 ${v.match} · ${g.ply}/100차례</h2>${g.result?`<div class="result-line">${esc(g.result.reason)}</div>`:''}<ol id="move-log">${v.log.map(e=>`<li>${e.p===me?'나':'상대'} · ${names[e.moved]} ${e.drop?'재투입':pos(e.from)} → ${pos(e.to)}${e.captured?' · '+names[e.captured]+' 포획':''}${e.promoted?' · 승급':''}</li>`).join('')||'<li>첫 수를 기다리고 있어요.</li>'}</ol></section><section class="mini-card"><h2>이 방의 경기 결과</h2>${v.past.map(p=>`<p>${p.match}경기 · ${esc(p.result.reason)} · ${p.ply}차례</p>`).join('')||'<p>아직 완료된 경기가 없습니다.</p>'}<p class="note">재대결 시 선공을 교대합니다. 결과는 서버 재시작 전까지 보관됩니다.</p></section></aside></div>`}
$('#room').innerHTML=`<section class="mini-card"><div class="room-heading"><h2>친구 대전방</h2><strong class="room-code">${v.code}</strong></div><div class="players">${players.join('')}</div><input class="invite-link" id="invite-link" readonly aria-label="친구 초대 링크" value="${esc(invite)}"><div class="room-tools"><button id="copy-invite">초대 링크 복사</button><button id="leave-room">${v.phase==='active'?'기권하고 나가기':'방 나가기'}</button></div>${v.phase==='waiting'?`<div class="ready-area"><p>${v.players.length===1?'친구가 입장하면 준비 버튼을 누를 수 있어요.':'두 사람 모두 준비하면 경기가 시작돼요.'}</p><button id="ready" class="primary" ${v.players.length<2||v.players[me].ready||busy?'disabled':''}>${v.players[me].ready?'준비 완료':'준비하기'}</button></div>`:''}${v.phase==='finished'?`<button class="primary" id="rematch" ${v.players[me].rematch||busy?'disabled':''}>${v.players[me].rematch?'상대 재대결 동의를 기다리는 중':'재대결 신청'}</button>`:''}</section>${board}`;
$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(invite);status('초대 링크를 복사했어요. 친구에게 보내주세요.')}catch{$('#invite-link').select();status('초대 링크를 선택했어요. 복사해서 친구에게 보내주세요.')}};$('#leave-room').onclick=leave;$('#ready')?.addEventListener('click',()=>act('ready'));$('#rematch')?.addEventListener('click',()=>act('rematch'));document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>cell(Number(b.dataset.cell)));document.querySelectorAll('[data-drop]').forEach(b=>b.onclick=()=>{selection=selection?.drop===b.dataset.drop?null:{drop:b.dataset.drop};Sound.play('select');render()});}
async function act(type,action){if(busy||!view)return;busy=true;let data={version:view.version,requestId:rid(),...(action?{action}:{})};render();try{let v=await api('/rooms/'+roomCode+'/'+type,'POST',data);selection=null;busy=false;setView(v);render()}catch(e){busy=false;try{setView(await api('/rooms/'+roomCode))}catch{}render();status(e.message,true)}}
function cell(i){if(!myTurn())return;let a=moves().find(a=>a.to===i);if(a){act('move',a);return}if(view.game.board[i]?.p===view.you){selection=selection?.from===i?null:{from:i};Sound.play('select');render()}}
async function leave(){if(!confirm(view.phase==='active'?'기권하고 방을 나갈까요?':'대전방을 나갈까요?'))return;if(busy)return;busy=true;try{await api('/rooms/'+roomCode+'/leave','POST',{});joined=false;roomCode='';view=null;selection=null;store();history.replaceState(null,'',location.pathname);$('#room').hidden=true;$('#lobby').hidden=false;status('방에서 나왔어요. 새 방을 만들 수 있습니다.')}catch(e){status(e.message,true)}busy=false}
async function enter(create,code){if(busy)return;busy=true;try{let v=await api(create?'/rooms':'/rooms/'+code+'/join','POST',{},true);view=null;selection=null;busy=false;setView(v);history.replaceState(null,'',location.pathname+'?room='+roomCode)}catch(e){busy=false;status(e.message,true)}}
$('#create-room').onclick=()=>enter(true);$('#join-form').onsubmit=e=>{e.preventDefault();let code=$('#room-code').value.trim().toUpperCase();if(!/^[A-Z2-9]{6}$/.test(code)){status('6자리 초대 코드를 입력해주세요.',true);return}enter(false,code)};
async function poll(){if(stopped)return;if(joined&&!busy){try{setView(await api('/rooms/'+roomCode))}catch(e){status(e.message,true);if(e.code===404||e.code===403){joined=false;$('#room').hidden=true;$('#lobby').hidden=false;roomCode='';view=null;store()}if(e.code===401){stopped=true;status('게스트 연결이 만료됐습니다. 새로고침해서 다시 입장해주세요.',true)}}}setTimeout(poll,1500)}
Guest.ensure(async profile=>{try{try{let s=JSON.parse(sessionStorage.getItem('panludiq.online.v1')||'{}');token=s.token||'';roomCode=s.roomCode||''}catch{}if(!token){status('게임 서버를 준비하고 있어요. 첫 연결은 잠시 걸릴 수 있습니다.');let s=await api('/sessions','POST',{nickname:profile.nickname},true);token=s.token;store()}let target=new URLSearchParams(location.search).get('room')?.toUpperCase();if(target&&/^[A-Z2-9]{6}$/.test(target)){await enter(false,target)}else if(roomCode){try{setView(await api('/rooms/'+roomCode,'GET',undefined,true))}catch(e){if(e.code===401){token='';store();location.reload();return}roomCode='';store();status(e.message,true)}}else status('서버 연결됨 · 방을 만들거나 초대 코드를 입력하세요.');$('#create-room').disabled=false;$('#join-room').disabled=false;poll();if(!storage)status('임시 게스트 연결됨 · 저장이 제한되어 새로고침 시 복구되지 않습니다.')}catch(e){status(e.message+' 새로고침해서 다시 연결할 수 있습니다.',true)}});
})();
